function pickTarget() {
  const npcs = sdk.getNearbyNpcs();
  const targets = npcs.filter(n => {
    if (!n.options?.includes('Attack')) return false;
    // If healthPercent is explicitly 0 AND hp 0, it's dead
    if (n.healthPercent === 0 && n.hp === 0) return false;
    if (n.inCombat) return false;
    return true;
  });
  const priority = (name) => {
    const n = name.toLowerCase();
    if (n === 'man' || n === 'woman') return 1;
    if (n === 'guard') return 2;
    if (n === 'chicken') return 3;
    if (n === 'rat' || n === 'giant rat') return 4;
    return 9;
  };
  targets.sort((a, b) => priority(a.name) - priority(b.name) || a.distance - b.distance);
  return targets[0];
}

